174	<body>
175	  <main>
176	    <h1 class="visually-hidden">Animated Circle</h1>
177	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
178	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
179	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
180	      </svg>
181	    </button>
182	    <p class="status" id="status" role="status" aria-atomic="true">Blue</p>
183	    <p class="hint" id="hint"><span class="verb">Click</span> to change color (or press <kbd>Space</kbd> or <kbd>Enter</kbd>; hold <kbd>Shift</kbd> to go back; arrow keys also work; <kbd>Home</kbd>/<kbd>End</kbd> jump to first/last)</p>
184	  </main>
185	  <script>
186	    const button = document.querySelector('button');
187	    const status = document.querySelector('.status');
188	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
189	    const storageKey = 'circle-color';
190	
191	    // Safely retrieve saved color from localStorage, returning null if unavailable
192	    function loadColor() {
193	      try {
194	        return localStorage.getItem(storageKey);
195	      } catch {
196	        return null;
197	      }
198	    }
199	
200	    // Safely save color to localStorage, silently failing if unavailable
201	    function saveColor(color) {
202	      try {
203	        localStorage.setItem(storageKey, color);
204	      } catch {}
205	    }
206	
207	    const savedColor = loadColor();
208	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
209	
210	    // Apply current color to button and update status display
211	    function applyColor() {
212	      const color = colors[index];
213	      if (color === 'blue') {
214	        delete button.dataset.color;
215	      } else {
216	        button.dataset.color = color;
217	      }
218	      status.textContent = color[0].toUpperCase() + color.slice(1);
219	    }
220	
221	    // Cycle color by step amount and trigger pulse animation
222	    function changeColor(step) {
223	      index = (index + step + colors.length) % colors.length;
224	      applyColor();
225	      saveColor(colors[index]);
226	
227	      button.classList.remove('color-changed');
228	      void button.offsetWidth;
229	      button.classList.add('color-changed');
230	    }
231	
232	    applyColor();
233	    // Enable transitions only after the restored color has been painted
234	    requestAnimationFrame(() => {
235	      requestAnimationFrame(() => {
236	        button.classList.remove('no-transition');
237	      });
238	    });
239	
240	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
241	    const hoverQuery = matchMedia('(hover: none)');
242	    const verbSpan = document.querySelector('.hint .verb');
243	    function updateVerb() {
244	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
245	    }
246	    updateVerb();
247	    hoverQuery.addEventListener('change', updateVerb);
248	
249	    // Space and Enter activate through the native click, but keyboard-synthesized
250	    // clicks don't reliably carry shiftKey, so remember it from the key events
251	    let shiftHeld = false;
252	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
253	    button.addEventListener('keyup', (event) => {
254	      if (isActivationKey(event)) shiftHeld = event.shiftKey;
255	    });
256	    button.addEventListener('blur', () => {
257	      shiftHeld = false;
258	    });
259	
260	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
261	    button.addEventListener('keydown', (event) => {
262	      if (isActivationKey(event)) {
263	        shiftHeld = event.shiftKey;
264	        // Holding Enter would otherwise fire a click on every repeat
265	        if (event.repeat && event.key === 'Enter') event.preventDefault();
266	        return;
267	      }
268	      if (event.altKey || event.ctrlKey || event.metaKey) return;
269	      if (event.key in keySteps) {
270	        event.preventDefault();
271	        changeColor(keySteps[event.key]);
272	      } else if (event.key === 'Home') {
273	        event.preventDefault();
274	        changeColor(-index);
275	      } else if (event.key === 'End') {
276	        event.preventDefault();
277	        changeColor(colors.length - 1 - index);
278	      }
279	    });
280	    button.addEventListener('click', (event) => {
281	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
282	      shiftHeld = false;
283	    });
284	    button.addEventListener('animationend', () => {
285	      button.classList.remove('color-changed');
286	    });
287	    // Sync color across tabs when storage changes
288	    addEventListener('storage', (event) => {
289	      if (event.key === storageKey && event.newValue && colors.includes(event.newValue)) {
290	        index = colors.indexOf(event.newValue);
291	        applyColor();
292	      }
293	    });
294	  </script>
295	</body>
296	</html>
